std::string text = "Error 404 on page /api/users";
std::regex pattern("Error (\\d+) on page (.*)");
std::smatch results;

// Search the text and populate 'results'
std::regex_search(text, results, pattern);

// Accessing the capture groups (subexpressions)
// results[0] is the full match ("Error 404...")
std::string error_code = results[1].str(); // "404"
std::string page_path = results[2];        // "/api/users"

// Check if a group matched (non-optional groups usually match if results[0] does)
if (results[2].matched) {
    // ... process path
}
